CREATE OR REPLACE FUNCTION public._rank_rows(_sid uuid,_scope text,_period text,_country text,_day date,_viewer uuid) RETURNS TABLE(entity uuid,rnk bigint,points bigint,streak integer,joined timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH bounds AS (SELECT CASE _period WHEN 'today' THEN _day WHEN 'week' THEN date_trunc('week',_day)::date ELSE s.starts_on END since FROM public.seasons s WHERE s.id=_sid), access AS (SELECT NOT EXISTS(SELECT 1 FROM public.challenges c WHERE c.season_id=_sid AND NOT c.public_board) OR EXISTS(SELECT 1 FROM public.season_entries WHERE user_id=_viewer AND season_id=_sid) allowed), base AS (SELECT e.user_id entity,(coalesce(sum(ds.total),0)+CASE WHEN _period='season' THEN coalesce((SELECT sum(bp.points) FROM public.bonus_points bp WHERE bp.user_id=e.user_id AND bp.season_id=_sid AND (bp.awarded_at AT TIME ZONE p.timezone)::date<=_day),0) ELSE 0 END)::bigint points,coalesce((SELECT d.streak FROM public.daily_scores d WHERE d.user_id=e.user_id AND d.season_id=_sid AND d.day<=_day ORDER BY d.day DESC LIMIT 1),0) streak,e.joined_at joined FROM public.season_entries e JOIN public.profiles p ON p.id=e.user_id CROSS JOIN bounds b CROSS JOIN access a LEFT JOIN public.daily_scores ds ON ds.user_id=e.user_id AND ds.season_id=_sid AND ds.day BETWEEN b.since AND _day WHERE a.allowed AND _scope<>'crews' AND e.season_id=_sid AND e.joined_at<(_day+1)::timestamp AT TIME ZONE p.timezone AND (_scope<>'country' OR p.country_code=_country) AND (p.show_on_public_board OR e.user_id=_viewer OR EXISTS(SELECT 1 FROM public.challenges ch JOIN public.season_entries ce ON ce.season_id=ch.season_id WHERE ch.season_id=_sid AND NOT ch.public_board AND ce.user_id=_viewer)) GROUP BY e.user_id,e.joined_at,p.timezone UNION ALL SELECT c.id,(coalesce((SELECT sum(total) FROM public.daily_scores ds WHERE ds.season_id=_sid AND ds.day BETWEEN b.since AND _day AND ds.user_id IN (SELECT user_id FROM public.crew_members WHERE crew_id=c.id)),0)+CASE WHEN _period='season' THEN coalesce((SELECT sum(bp.points) FROM public.bonus_points bp WHERE bp.season_id=_sid AND bp.user_id IN(SELECT user_id FROM public.crew_members WHERE crew_id=c.id) AND bp.awarded_at<(_day+1)::timestamp AT TIME ZONE 'Africa/Tunis'),0) ELSE 0 END)::bigint,0,c.created_at FROM public.crews c CROSS JOIN bounds b CROSS JOIN access a WHERE a.allowed AND _scope='crews' AND c.season_id=_sid AND c.created_at<(_day+1)::timestamp AT TIME ZONE 'Africa/Tunis' AND (c.is_public OR EXISTS(SELECT 1 FROM public.crew_members m WHERE m.crew_id=c.id AND m.user_id=_viewer))) SELECT entity,row_number() OVER(ORDER BY points DESC,streak DESC,joined ASC,entity),points,streak,joined FROM base $$;
CREATE OR REPLACE FUNCTION public.profile_summary(_season_id uuid,_share boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); result jsonb; viewer uuid; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; PERFORM public._award_badges(uid,_season_id); viewer:=CASE WHEN _share THEN NULL ELSE uid END; SELECT jsonb_build_object('points',coalesce((SELECT sum(total) FROM public.daily_scores WHERE user_id=uid AND season_id=_season_id),0)+coalesce((SELECT sum(points) FROM public.bonus_points WHERE user_id=uid AND season_id=_season_id),0),'streak',coalesce((SELECT streak FROM public.daily_scores WHERE user_id=uid AND season_id=_season_id AND day<=public._local_today(uid) ORDER BY day DESC LIMIT 1),0),'rank',(SELECT r.rnk FROM public._rank_rows(_season_id,'country','season',p.country_code,public._local_today(uid),uid) r WHERE r.entity=uid),'stat',public._best_habit_stat(uid,_season_id,viewer),'badges',coalesce((SELECT jsonb_agg(key) FROM public.badges WHERE user_id=uid AND season_id=_season_id AND (NOT _share OR p.faith_public OR key<>'salat5')),'[]'::jsonb),'crew',(SELECT jsonb_build_object('id',c.id,'name',c.name) FROM public.crew_members m JOIN public.crews c ON c.id=m.crew_id WHERE m.user_id=uid AND c.season_id=_season_id LIMIT 1),'mode',(SELECT mode FROM public.season_entries WHERE user_id=uid AND season_id=_season_id)) INTO result FROM public.profiles p WHERE p.id=uid; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.leaderboard(_season_id uuid,_scope text,_period text,_country_code text DEFAULT 'TN') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.scoreboard_v4(_season_id,_scope,_period,_country_code,'total') $$;
CREATE OR REPLACE FUNCTION public.solo_ghost(_season_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); d date; best record; cur bigint; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; d:=public._local_today(uid); SELECT g::date starts_on,coalesce(sum(ds.total),0)::bigint points INTO best FROM public.seasons s CROSS JOIN LATERAL generate_series(s.starts_on,least(s.ends_on-6,d-7),interval '1 day') g LEFT JOIN public.daily_scores ds ON ds.user_id=uid AND ds.season_id=s.id AND ds.day BETWEEN g::date AND g::date+6 WHERE EXISTS(SELECT 1 FROM public.season_entries e WHERE e.user_id=uid AND e.season_id=s.id) GROUP BY g,s.id ORDER BY points DESC,g ASC LIMIT 1; IF best.points IS NULL THEN SELECT s.starts_on,coalesce(sum(ds.total),0)::bigint points INTO best FROM public.seasons s LEFT JOIN public.daily_scores ds ON ds.season_id=s.id AND ds.user_id=uid AND ds.day BETWEEN s.starts_on AND least(s.starts_on+6,d) WHERE s.id=_season_id GROUP BY s.starts_on; END IF; SELECT coalesce(sum(total),0) INTO cur FROM public.daily_scores WHERE user_id=uid AND season_id=_season_id AND day BETWEEN d-6 AND d; RETURN jsonb_build_object('points',best.points,'starts_on',best.starts_on,'current',cur); END $$;
CREATE FUNCTION public.wrapped_summary(_season_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); s public.seasons; p public.profiles; r jsonb; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; SELECT * INTO s FROM public.seasons WHERE id=_season_id; SELECT * INTO p FROM public.profiles WHERE id=uid; IF NOT EXISTS(SELECT 1 FROM public.season_entries WHERE season_id=_season_id AND user_id=uid) THEN RAISE EXCEPTION 'forbidden'; END IF; IF public._local_today(uid)<s.ends_on AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=uid AND email='demo@lezgo.app') THEN RETURN jsonb_build_object('locked',true,'ends_on',s.ends_on); END IF; SELECT jsonb_build_object('locked',false,'season',to_jsonb(s),'handle',p.handle,'days',(SELECT count(DISTINCT ci.day) FROM public.checkins ci JOIN public.user_habits h ON h.id=ci.user_habit_id WHERE ci.user_id=uid AND h.season_id=_season_id AND ci.value>0),'rank',(SELECT r.rnk FROM public._rank_rows(_season_id,'country','season',p.country_code,least(public._local_today(uid),s.ends_on),uid) r WHERE r.entity=uid),'stats',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT ht.key,ht.name,h.unit,h.kind,CASE WHEN ht.key='sleep' THEN round(avg(ci.value),2) WHEN h.kind='count' THEN sum(ci.value) ELSE count(ci.id) FILTER(WHERE ci.value>0)::numeric END value FROM public.user_habits h JOIN public.habit_templates ht ON ht.id=h.template_id JOIN public.checkins ci ON ci.user_habit_id=h.id WHERE h.user_id=uid AND h.season_id=_season_id AND (NOT ht.is_faith OR p.faith_public) GROUP BY ht.key,ht.name,h.unit,h.kind,h.position ORDER BY count(ci.id) DESC,h.position LIMIT 5) x),'[]'::jsonb),'lift_days',(SELECT count(DISTINCT day) FROM public.lift_sets WHERE user_id=uid AND day BETWEEN s.starts_on AND s.ends_on),'bosses_done',(SELECT count(DISTINCT boss_id) FROM public.bonus_points WHERE user_id=uid AND season_id=_season_id),'bosses_total',(SELECT count(*) FROM public.bosses WHERE season_id=_season_id),'crew',(SELECT jsonb_build_object('name',c.name,'code',c.code) FROM public.crews c JOIN public.crew_members m ON m.crew_id=c.id WHERE m.user_id=uid AND c.season_id=_season_id LIMIT 1),'capsule',(SELECT note FROM public.time_capsules WHERE user_id=uid AND season_id=_season_id)) INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.wrapped_summary(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.wrapped_summary(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public._rank_rows(uuid,text,text,text,date,uuid),public._rank_rows_metric(uuid,text,text,text,date,uuid,text),public._best_habit_stat(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;